import base64
import json
import os
from typing import Any, Dict, Optional

import dashscope
from dashscope import MultiModalConversation


def _image_to_data_url(image_path: str) -> str:
    with open(image_path, "rb") as f:
        encoded = base64.b64encode(f.read()).decode("utf-8")
    ext = os.path.splitext(image_path)[1].lower().lstrip(".") or "png"
    mime = "jpeg" if ext in {"jpg", "jpeg"} else ext
    if mime not in {"png", "jpeg", "gif", "webp", "bmp"}:
        mime = "png"
    return f"data:image/{mime};base64,{encoded}"


def generate_visual_description(image_path: str, max_words: int = 30) -> str:
    api_key = os.getenv("DASHSCOPE_API_KEY")
    if not api_key:
        raise EnvironmentError("DASHSCOPE_API_KEY is required")

    dashscope.api_key = api_key
    image_url = _image_to_data_url(image_path)

    response = MultiModalConversation.call(
        model="qwen-vl-max",
        messages=[
            {
                "role": "user",
                "content": [
                    {"image": image_url},
                    {
                        "text": (
                            "Write a short visual description of this image in one sentence, "
                            f"using at most {max_words} words."
                        )
                    },
                ],
            }
        ],
        result_format="message",
    )

    try:
        content = response.output["choices"][0]["message"]["content"]
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict):
                    if "text" in item:
                        parts.append(item["text"])
                    elif "content" in item and isinstance(item["content"], str):
                        parts.append(item["content"])
                elif isinstance(item, str):
                    parts.append(item)
            description = " ".join(parts).strip()
        elif isinstance(content, str):
            description = content.strip()
        else:
            description = str(content).strip()
    except Exception:
        description = str(response)

    return description


def main(image_path: str) -> Dict[str, Any]:
    return {"description": generate_visual_description(image_path)}
